INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0031-1','math','高中',13,'hs-kp-0031','single_choice',0.45,'函数 f(x)=√(x-1) 的定义域是？','[{"key":"A","text":"x≥1"},{"key":"B","text":"x>1"},{"key":"C","text":"x≤1"},{"key":"D","text":"x≠1"}]','A','偶次根式非负：x-1≥0 → x≥1','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0032-1','math','高中',13,'hs-kp-0032','single_choice',0.55,'f(x+1) 定义域为 [-1,1]，则 f(x) 定义域？','[{"key":"A","text":"[0,2]"},{"key":"B","text":"[-1,1]"},{"key":"C","text":"[-0,0]"},{"key":"D","text":"[1,3]"}]','A','令 t=x+1，t∈[-2,2]','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0033-1','math','高中',13,'hs-kp-0033','single_choice',0.65,'f(x)=x²-5x+1 在 [1,5] 单调性？','[{"key":"A","text":"先减后增"},{"key":"B","text":"先增后减"},{"key":"C","text":"单调递增"},{"key":"D","text":"单调递减"}]','A','对称轴 x=5/2 ∈ [1,5] → 先减后增','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0034-1','math','高中',13,'hs-kp-0034','single_choice',0.75,'若 y=f(u) 增，u=x² 在 (0,+∞) 减，则 y=f(x²) 在 (0,+∞) 单调？','[{"key":"A","text":"递减"},{"key":"B","text":"递增"},{"key":"C","text":"不单调"},{"key":"D","text":"无法确定"}]','A','同增异减：外层增内层减 → 复合减','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0035-1','math','高中',13,'hs-kp-0035','single_choice',0.35,'若 f 与 g 均在 R 上递增，则 f+g 单调？','[{"key":"A","text":"递增"},{"key":"B","text":"递减"},{"key":"C","text":"不单调"},{"key":"D","text":"无法判断"}]','A','增+增=增','template-hs','approved','通用');
